cat > src/claim-office.spec.ts <<'EOF'
import { describe, it, expect } from "vitest";
import { runScenario } from "./claim-office.js";

describe("MHPCO Claim Office", () => {
  describe("quote: base premiums", () => {
    it.todo("empty item list → premium 5 G (only the processing fee)");
    it.todo("single sword (0 years, no modifiers) → base 100 + 10 first insurance + 5 fee = 115 G");
    it.todo("single amulet → base 60 G (+10% first insurance + 5 fee = 71 G)");
    it.todo("single staff → base 80 G (+10% first insurance + 5 fee = 93 G)");
    it.todo("single potion → base 40 G (+10% first insurance + 5 fee = 49 G)");
  });

  describe("quote: components and building blocks", () => {
    it.todo("2 runes → 50 G base premium (60 G total)");
    it.todo("3 runes → 60 G base premium, block applies (71 G total)");
    it.todo("4 runes → 100 G base premium, no block (115 G total)");
    it.todo("7 runes → 175 G base premium (198 G total, 197.5 rounded up)");
    it.todo("2 runes + 1 moonstone → 75 G base premium, no block for different types (88 G total)");
    it.todo("3 runes + 3 moonstones → 120 G base premium, two separate blocks (137 G total)");
  });

  describe("quote: item-specific modifiers", () => {
    it.todo("cursed sword → 50 % surcharge on the sword's base premium (165 G newcomer)");
    it.todo("sword with enchantment 5 → high-enchantment surcharge applies (30 G)");
    it.todo("sword with enchantment 4 → no high-enchantment surcharge");
    it.todo("cursed sword with enchantment 5 → both surcharges apply (80 G)");
    it.todo("cursed sword + plain amulet → surcharge applies only to the sword (210 G before policy modifiers)");
  });

  describe("quote: policy-wide modifiers", () => {
    it.todo("customer with exactly 2 years → 20 % loyalty discount applies");
    it.todo("customer with 1 year → no loyalty discount");
    it.todo("second quote in a scenario → 15 % follow-up discount applies");
    it.todo("first insurance surcharge still applies on a follow-up contract for a new item");
    it.todo("long-standing customer's second contract, cursed sword enchantment 7 → 160 G");
  });

  describe("quote: rounding and errors", () => {
    it.todo("premium of 197.5 G is rounded up to 198 G (in MHPCO's favor)");
    it.todo("unknown item type (broomstick) → throws an error");
  });

  describe("claim: standard reimbursement and deductible", () => {
    it.todo("regular steel sword enchantment 3, damage 500 G → payout 400 G");
    it.todo("rune damage 200 G → payout 100 G (no special clause)");
    it.todo("dragon attack damages sword (500) and amulet (300) → payout 600 G, deductible per damaged item");
  });

  describe("claim: special clauses", () => {
    it.todo("steel sword enchantment 9, damage 1000 G → payout 400 G (50 % then deductible)");
    it.todo("dragon-material sword enchantment 5, damage 800 G → payout 700 G (full reimbursement)");
    it.todo("dragon-material sword enchantment 9, damage 1000 G → payout 400 G (50 % rule wins)");
    it.todo("dragon-material sword exactly enchantment 8, damage 1000 G → payout 400 G");
  });

  describe("claim: insurance sum and cap", () => {
    it.todo("sword + amulet → insurance sum 1600 G, cap 3200 G (remainingCap after zero-payout claim)");
    it.todo("cursed sword → cap 2000 G based on unmodified insurance value");
    it.todo("sword + 3 runes → insurance sum 1750 G, cap 3500 G");
    it.todo("two swords → insurance sum 2000 G, cap 4000 G");
    it.todo("two successive 1500 G claims on a sword → 1400 G then 600 G, remaining cap 0");
    it.todo("payout of 350.5 G is rounded down to 350 G (in MHPCO's favor)");
  });

  describe("claim: multiple items of the same type and errors", () => {
    it.todo("two damaged swords on a two-sword policy → each has its own deductible");
    it.todo("more sword damages than swords insured → throws an error");
    it.todo("damage to an item not part of the policy (amulet when only sword insured) → throws an error");
    it.todo("damage with an unknown item type → throws an error");
    it.todo("damage with negative amount (-200) → throws an error");
  });

  describe("scenario", () => {
    it.todo("results array matches steps in length and order (schema example: quote then claim)");
  });
});
EOF
